class Solution { public int uniqueMorseRepresentations(String[] words){String[] code={".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."};Set<String> seen=new HashSet<>();for(String word:words){StringBuilder encoded=new StringBuilder();for(char c:word.toCharArray())encoded.append(code[c-'a']);seen.add(encoded.toString());}return seen.size();} }
